content.content:
1	/**
2	 * T2.6 CALL-E webhook receiver.
3	 *
4	 * CALL-E does not sign webhook requests. The path secret is the first gate.
5	 * The envelope only selects an authoritative GET /v1/calls/{id}. No call,
6	 * item, result, or billing state is ever taken from the webhook body.
7	 */
8	
9	import { terminalStateFor } from "../_shared/poll.ts";
10	import type { CallStatus } from "../_shared/fixtures.ts";
11	import { recordCallEvent } from "../_shared/events.ts";
12	
13	const EVENT_ID_HEADER = "call-e-event-id";
14	const MAX_BODY_BYTES = 128 * 1024;
15	const EVENT_ID_PATTERN = /^evt_[A-Za-z0-9_-]+$/;
16	const CALL_ID_PATTERN = /^call_[A-Za-z0-9_-]+$/;
17	const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
18	
19	// A claim is reclaimed once this much wall clock has passed without a
20	// terminal state, so a killed or failed invocation cannot strand an id.
21	const REFRESH_LEASE_MS = 5 * 60 * 1000;
22	const TERMINAL_EVENT_TYPES = new Set([
23	  "call.completed",
24	  "call.failed",
25	  "call.result_validation_failed",
26	]);
27	
28	const PENDING = "pending";
29	const REFRESHING = "refreshing";
30	const REFETCHED = "refetched";
31	const IGNORED = "ignored";
32	
33	export type WebhookDeps = {
34	  apiUrl: string;
35	  serviceRoleKey: string;
36	  webhookSecret: string;
37	  calleApiBase: string;
38	  calleApiKey: string;
39	  fetch: typeof fetch;
40	};
41	
42	type WebhookEnvelope = {
43	  id: string;
44	  type: "call.completed" | "call.failed" | "call.result_validation_failed";
45	  created_at: string;
46	  data: { id: string };
47	};
48	
49	type AuthoritativeCall = {
50	  id: string;
51	  status: string;
52	  metadata: { call_run_id: string };
53	};
54	
55	export function requireNamedEnv(
56	  name: string,
57	  getEnv: (key: string) => string | undefined = (key) => Deno.env.get(key),
58	): string {
59	  const value = getEnv(name);
60	  if (!value) throw new Error(`missing ${name}`);
61	  return value;
62	}
63	
64	export function webhookUrl(apiUrl: string, secret: string): string {
65	  return `${apiUrl.replace(/\/+$/, "")}/functions/v1/calle-webhook/${secret}`;
66	}
67	
68	export function presentedWebhookSecret(pathname: string): string | null {
69	  const marker = "/calle-webhook/";
70	  const index = pathname.indexOf(marker);
71	  if (index === -1) return null;
72	  const secret = pathname.slice(index + marker.length).replace(/\/+$/, "");
73	  return secret || null;
74	}
75	
76	export function webhookSecretsMatch(presented: string, expected: string): boolean {
77	  const encoder = new TextEncoder();
78	  const left = encoder.encode(presented);
79	  const right = encoder.encode(expected);
80	  if (left.length !== right.length) return false;
81	  let diff = 0;
82	  for (let index = 0; index < left.length; index++) diff |= left[index] ^ right[index];
83	  return diff === 0;
84	}
85	
86	function restUrl(apiUrl: string, path: string, query = ""): string {
87	  return `${apiUrl.replace(/\/+$/, "")}/rest/v1/${path}${query ? `?${query}` : ""}`;
88	}
89	
90	function serviceHeaders(key: string, prefer?: string): HeadersInit {
91	  const headers: Record<string, string> = {
92	    apikey: key,
93	    authorization: `Bearer ${key}`,
94	    "content-type": "application/json",
95	  };
96	  if (prefer) headers.prefer = prefer;
97	  return headers;
98	}
99	
100	export function parseWebhookEnvelope(body: string, headerEventId: string): WebhookEnvelope | null {
101	  if (!EVENT_ID_PATTERN.test(headerEventId)) return null;
102	  let value: unknown;
103	  try {
104	    value = JSON.parse(body);
105	  } catch {
106	    return null;
107	  }
108	  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
109	  const envelope = value as Partial<WebhookEnvelope>;
110	  if (
111	    envelope.id !== headerEventId ||
112	    typeof envelope.id !== "string" ||
113	    typeof envelope.type !== "string" ||
114	    !TERMINAL_EVENT_TYPES.has(envelope.type) ||
115	    typeof envelope.created_at !== "string" ||
116	    Number.isNaN(Date.parse(envelope.created_at)) ||
117	    !envelope.data ||
118	    typeof envelope.data !== "object" ||
119	    typeof envelope.data.id !== "string" ||
120	    !CALL_ID_PATTERN.test(envelope.data.id)
121	  ) return null;
122	  return envelope as WebhookEnvelope;
123	}
124	
125	function parseAuthoritativeCall(value: unknown, expectedCallId: string): AuthoritativeCall | null {
126	  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
127	  const call = value as Partial<AuthoritativeCall>;
128	  if (
129	    call.id !== expectedCallId ||
130	    typeof call.status !== "string" ||
131	    call.status.trim().length === 0 ||
132	    !call.metadata ||
133	    typeof call.metadata !== "object" ||
134	    typeof call.metadata.call_run_id !== "string" ||
135	    !UUID_PATTERN.test(call.metadata.call_run_id)
136	  ) return null;
137	  return call as AuthoritativeCall;
138	}
139	
140	export function depsFromEnv(
141	  getEnv: (key: string) => string | undefined = (key) => Deno.env.get(key),
142	  fetchImpl: typeof fetch = fetch,
143	): WebhookDeps {
144	  return {
145	    apiUrl: requireNamedEnv("ORMA_API_URL", getEnv),
146	    serviceRoleKey: requireNamedEnv("SUPABASE_SERVICE_ROLE_KEY", getEnv),
147	    webhookSecret: requireNamedEnv("ORMA_WEBHOOK_SECRET", getEnv),
148	    calleApiBase: requireNamedEnv("CALLE_API_BASE", getEnv),
149	    calleApiKey: requireNamedEnv("CALLE_API_KEY", getEnv),
150	    fetch: fetchImpl,
151	  };
152	}
153	
154	/** Returns true when the event id was already recorded, which marks a redelivery. */
155	async function insertPendingEvent(deps: WebhookDeps, eventId: string): Promise<boolean> {
156	  const response = await deps.fetch(restUrl(deps.apiUrl, "webhook_events"), {
157	    method: "POST",
158	    headers: serviceHeaders(deps.serviceRoleKey, "return=minimal"),
159	    body: JSON.stringify({ event_id: eventId, type: PENDING }),
160	  });
161	  if (response.status === 409) return true;
162	  if (!response.ok) throw new Error("webhook event record failed");
163	  return false;
164	}
165	
166	async function claimPendingEvent(deps: WebhookDeps, eventId: string, now = Date.now()): Promise<boolean> {
167	  const staleBefore = new Date(now - REFRESH_LEASE_MS).toISOString();
168	  const query = new URLSearchParams({
169	    event_id: `eq.${eventId}`,
170	    or: `(type.eq.${PENDING},and(type.eq.${REFRESHING},received_at.lt.${staleBefore}))`,
171	  });
172	  const response = await deps.fetch(restUrl(deps.apiUrl, "webhook_events", query.toString()), {
173	    method: "PATCH",
174	    headers: serviceHeaders(deps.serviceRoleKey, "return=representation"),
175	    body: JSON.stringify({ type: REFRESHING, received_at: new Date(now).toISOString() }),
176	  });
177	  if (!response.ok) throw new Error("webhook event claim failed");
178	  const rows: unknown = await response.json();
179	  return Array.isArray(rows) && rows.length === 1;
180	}
181	
182	async function setEventState(deps: WebhookDeps, eventId: string, type: string): Promise<void> {
183	  const query = new URLSearchParams({ event_id: `eq.${eventId}`, type: `eq.${REFRESHING}` });
184	  const response = await deps.fetch(restUrl(deps.apiUrl, "webhook_events", query.toString()), {
185	    method: "PATCH",
186	    headers: serviceHeaders(deps.serviceRoleKey, "return=minimal"),
187	    body: JSON.stringify({ type }),
188	  });
189	  if (!response.ok) throw new Error("webhook event state update failed");
190	}
191	
192	async function fetchAuthoritativeCall(deps: WebhookDeps, callId: string): Promise<AuthoritativeCall | null> {
193	  const response = await deps.fetch(
194	    `${deps.calleApiBase.replace(/\/+$/, "")}/v1/calls/${encodeURIComponent(callId)}`,
195	    { headers: { authorization: `Bearer ${deps.calleApiKey}` } },
196	  );
197	  if (!response.ok) throw new Error(`CALL-E re-fetch returned HTTP ${response.status}`);
198	  return parseAuthoritativeCall(await response.json(), callId);
199	}
200	
201	/**
202	 * Moves the run to the state the re-fetch reports, and only while the run is
203	 * still pending. The webhook and the poll both write here, so the conditional
204	 * PATCH is what makes exactly one of them win. The body never supplies a
205	 * state, only the authoritative GET does.
206	 */
207	type RefetchOutcome = "applied" | "already_resolved" | "not_terminal";
208	
209	async function terminaliseFromRefetch(
210	  deps: WebhookDeps,
211	  call: AuthoritativeCall,
212	  redelivered: boolean,
213	): Promise<RefetchOutcome> {
214	  const state = terminalStateFor(call.status as CallStatus);
215	  if (!state) return "not_terminal";
216	  const query = new URLSearchParams({
217	    id: `eq.${call.metadata.call_run_id}`,
218	    state: "in.(dispatched,awaiting_result)",
219	  });
220	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
221	    method: "PATCH",
222	    headers: serviceHeaders(deps.serviceRoleKey, "return=representation"),
223	    body: JSON.stringify({ state, poll_after: null }),
224	  });
225	  if (!response.ok) throw new Error("call run terminalisation failed");
226	  const rows = await response.json() as unknown[];
227	  if (Array.isArray(rows) && rows.length === 1) return "applied";
228	  // Zero matched rows has two writers. The poll may have moved the run, and
229	  // then the re-fetched status is a superseded observation. Or an earlier
230	  // attempt at this same event moved it and then failed on a timeline insert.
231	  // A first delivery cannot be the second case, so only a redelivery looks.
232	  if (redelivered && await earlierAttemptApplied(deps, call.metadata.call_run_id, state)) return "applied";
233	  return "already_resolved";
234	}
235	
236	/**
237	 * An earlier attempt at this event wrote the run when the run holds exactly the
238	 * re-fetched terminal state and no poll row claims a terminal state. Every
239	 * poll write to a terminal state records a `polled` row naming that state.
240	 */
241	async function earlierAttemptApplied(deps: WebhookDeps, runId: string, state: string): Promise<boolean> {
242	  const runQuery = new URLSearchParams({ select: "state", id: `eq.${runId}`, limit: "1" });
243	  const runResponse = await deps.fetch(restUrl(deps.apiUrl, "call_runs", runQuery.toString()), {
244	    headers: serviceHeaders(deps.serviceRoleKey),
245	  });
246	  if (!runResponse.ok) throw new Error("call run attribution read failed");
247	  const runs = await runResponse.json() as { state?: string }[];
248	  if (!Array.isArray(runs) || runs[0]?.state !== state) return false;
249	  const eventQuery = new URLSearchParams({
250	    select: "id",
251	    call_run_id: `eq.${runId}`,
252	    kind: "eq.polled",
253	    "detail->>state": "in.(completed,failed,canceled)",
254	    limit: "1",
255	  });
256	  const eventResponse = await deps.fetch(restUrl(deps.apiUrl, "call_events", eventQuery.toString()), {
257	    headers: serviceHeaders(deps.serviceRoleKey),
258	  });
259	  if (!eventResponse.ok) throw new Error("call run attribution read failed");
260	  const polled = await eventResponse.json() as unknown[];
261	  return Array.isArray(polled) && polled.length === 0;
262	}
263	
264	async function hasMatchingOrmaRun(deps: WebhookDeps, call: AuthoritativeCall): Promise<boolean> {
265	  const query = new URLSearchParams({
266	    select: "id",
267	    id: `eq.${call.metadata.call_run_id}`,
268	    calle_call_id: `eq.${call.id}`,
269	    limit: "1",
270	  });
271	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
272	    headers: serviceHeaders(deps.serviceRoleKey),
273	  });
274	  if (!response.ok) throw new Error("call run ownership check failed");
275	  const rows: unknown = await response.json();
276	  return Array.isArray(rows) && rows.length === 1;
277	}
278	
279	export function createWebhookHandler(deps: WebhookDeps): (request: Request) => Promise<Response> {
280	  return async (request) => {
281	    if (request.method !== "POST") {
282	      return new Response(null, { status: 405, headers: { allow: "POST" } });
283	    }
284	    const presented = presentedWebhookSecret(new URL(request.url).pathname);
285	    if (!presented || !webhookSecretsMatch(presented, deps.webhookSecret)) {
286	      return new Response(null, { status: 401 });
287	    }
288	    const headerEventId = request.headers.get(EVENT_ID_HEADER);
289	    if (!headerEventId) return new Response(null, { status: 400 });
290	    try {
291	      const body = await request.text();
292	      if (new TextEncoder().encode(body).byteLength > MAX_BODY_BYTES) {
293	        return new Response(null, { status: 413 });
294	      }
295	      const envelope = parseWebhookEnvelope(body, headerEventId);
296	      if (!envelope) return new Response(null, { status: 400 });
297	      const redelivered = await insertPendingEvent(deps, envelope.id);
298	      if (!await claimPendingEvent(deps, envelope.id)) return new Response(null, { status: 200 });
299	      try {
300	        const call = await fetchAuthoritativeCall(deps, envelope.data.id);
301	        if (!call || !await hasMatchingOrmaRun(deps, call)) {
302	          await setEventState(deps, envelope.id, IGNORED);
303	          return new Response(null, { status: 200 });
304	        }
305	        // Persist the transition before the timeline claims it, so a failed
306	        // write never leaves an entry asserting a state that never landed.
307	        // The event row is released to pending below, so this is retried.
308	        const outcome = await terminaliseFromRefetch(deps, call, redelivered);
309	        const eventDeps = { apiUrl: deps.apiUrl, serviceRoleKey: deps.serviceRoleKey, fetch: deps.fetch };
310	        await recordCallEvent(
311	          call.metadata.call_run_id,
312	          "webhook_received",
313	          { calle_call_id: call.id, event_type: envelope.type },
314	          eventDeps,
315	        );
316	        await recordCallEvent(
317	          call.metadata.call_run_id,
318	          "refetched",
319	          { calle_call_id: call.id, event_type: envelope.type, state: call.status, outcome },
320	          eventDeps,
321	        );
322	        await setEventState(deps, envelope.id, REFETCHED);
323	        return new Response(null, { status: 200 });
324	      } catch (error) {
325	        try {
326	          await setEventState(deps, envelope.id, PENDING);
327	        } catch (releaseError) {
328	          console.error("calle webhook event release failed", releaseError instanceof Error ? releaseError.message : "unknown error");
329	        }
330	        throw error;
331	      }
332	    } catch (error) {
333	      console.error("calle webhook re-fetch failed", error instanceof Error ? error.message : "unknown error");
334	      return new Response(null, { status: 500 });
335	    }
336	  };
337	}
338	
339	if (import.meta.main) Deno.serve(createWebhookHandler(depsFromEnv()));
340	
341	const testFn = (Deno as { test?: (name: string, fn: () => void | Promise<void>) => void }).test;
342	if (typeof testFn === "function" && !import.meta.main) {
343	  const event = (id = "evt_terminal"): Record<string, unknown> => ({
344	    id, type: "call.completed", created_at: "2026-09-13T12:00:00.000Z", data: { id: "call_terminal" },
345	  });
346	  const baseDeps = (fetchImpl: typeof fetch): WebhookDeps => ({
347	    apiUrl: "https://orma-api.nryn.dev", serviceRoleKey: "service-key",
348	    webhookSecret: "path-secret", calleApiBase: "https://api.call-e.test",
349	    calleApiKey: "calle-key", fetch: fetchImpl,
350	  });
351	  const request = (body: unknown = event(), eventId = "evt_terminal") => new Request(
352	    "https://orma-api.nryn.dev/functions/v1/calle-webhook/path-secret",
353	    { method: "POST", headers: { [EVENT_ID_HEADER]: eventId }, body: JSON.stringify(body) },
354	  );
355	
356	  testFn("rejects a request without the path secret before reading its body", async () => {
357	    const handler = createWebhookHandler(baseDeps(async () => { throw new Error("fetch must not be called"); }));
358	    const response = await handler(new Request("https://orma-api.nryn.dev/functions/v1/calle-webhook/wrong", {
359	      method: "POST", headers: { [EVENT_ID_HEADER]: "evt_terminal" }, body: "not json",
360	    }));
361	    if (response.status !== 401) throw new Error("missing secret must be rejected");
362	  });
363	
364	  testFn("rejects an envelope whose header id differs from its body id", async () => {
365	    const handler = createWebhookHandler(baseDeps(async () => { throw new Error("invalid envelope reached a dependency"); }));
366	    const response = await handler(request(event("evt_other")));
367	    if (response.status !== 400) throw new Error("header and body ids must match");
368	  });
369	
370	  testFn("accepts and re-fetches each terminal contract fixture, documented and recorded", async () => {
371	    const fixtures = [
372	      "webhook-call-completed.documented.json",
373	      "webhook-call-failed.documented.json",
374	      "webhook-result-validation-failed.documented.json",
375	      "webhook-call-failed.recorded.json",
376	    ];
377	    for (const fixture of fixtures) {
378	      const raw = await Deno.readTextFile(new URL(`../../../testdata/calle/${fixture}`, import.meta.url));
379	      const value = JSON.parse(raw) as {
380	        headers: { "call-e-event-id": string };
381	        body: { id: string; data: { id: string } };
382	      };
383	      const body = JSON.stringify(value.body);
384	      if (!parseWebhookEnvelope(body, value.headers["call-e-event-id"])) {
385	        throw new Error(`fixture ${fixture} did not match the receiver contract`);
386	      }
387	      const refetched: string[] = [];
388	      const handler = createWebhookHandler(baseDeps(async (input, init) => {
389	        const current = new Request(input, init);
390	        if (current.url.endsWith("/webhook_events") && current.method === "POST") return new Response(null, { status: 201 });
391	        if (current.url.includes("/webhook_events?") && current.method === "PATCH") {
392	          return Response.json([{ event_id: value.headers["call-e-event-id"] }]);
393	        }
394	        if (current.url.endsWith("/call_events") && current.method === "POST") return new Response(null, { status: 201 });
395	        if (current.url.endsWith(`/v1/calls/${value.body.data.id}`)) {
396	          refetched.push(value.body.data.id);
397	          return Response.json({ id: value.body.data.id, status: "completed", metadata: { call_run_id: "11111111-1111-4111-8111-111111111111" } });
398	        }
399	        if (current.url.includes("/call_runs?") && current.method === "GET") {
400	          return Response.json([{ id: "11111111-1111-4111-8111-111111111111" }]);
401	        }
402	        // The poll won this race. The receiver must still acknowledge.
403	        if (current.url.includes("/call_runs?") && current.method === "PATCH") return Response.json([]);
404	        throw new Error(`unexpected request ${current.method} ${current.url} while driving ${fixture}`);
405	      }));
406	      const response = await handler(new Request(
407	        "https://orma-api.nryn.dev/functions/v1/calle-webhook/path-secret",
408	        { method: "POST", headers: { [EVENT_ID_HEADER]: value.headers["call-e-event-id"] }, body },
409	      ));
410	      if (response.status !== 200) throw new Error(`fixture ${fixture} was not acknowledged`);
411	      if (refetched.length !== 1 || refetched[0] !== value.body.data.id) {
412	        throw new Error(`fixture ${fixture} did not re-fetch its own call id`);
413	      }
414	    }
415	  });
416	
417	  testFn("re-fetches the documented terminal envelope and never uses body metadata", async () => {
418	    const requests: Request[] = [];
419	    const handler = createWebhookHandler(baseDeps(async (input, init) => {
420	      const current = new Request(input, init);
421	      requests.push(current);
422	      if (current.url.endsWith("/webhook_events") && current.method === "POST") return new Response(null, { status: 201 });
423	      if (current.url.includes("/webhook_events?") && current.method === "PATCH") return Response.json([{ event_id: "evt_terminal" }]);
424	      if (current.url.endsWith("/call_events") && current.method === "POST") return new Response(null, { status: 201 });
425	      if (current.url.endsWith("/v1/calls/call_terminal")) {
426	        if (current.headers.get("authorization") !== "Bearer calle-key") throw new Error("CALL-E key missing");
427	        return Response.json({ id: "call_terminal", status: "completed", metadata: { call_run_id: "11111111-1111-4111-8111-111111111111" } });
428	      }
429	      if (current.url.includes("/call_runs?")) return Response.json([{ id: "11111111-1111-4111-8111-111111111111" }]);
430	      throw new Error(`unexpected request ${current.method} ${current.url}`);
431	    }));
