1	/**
2	 * T2.5 poll reconciliation.
3	 *
4	 * Webhooks get dropped, so polling is the safety net that makes a lost
5	 * delivery survivable. A dispatched run carries `poll_after` and the tick
6	 * advances it by re-fetching the authoritative call. Follow-up crosses tick
7	 * boundaries rather than looping, because a free Edge Function allows 150
8	 * seconds of wall clock per request.
9	 *
10	 * Whichever of the webhook and the poll arrives first wins. Every write here
11	 * is a conditional PATCH that only matches a still-pending run, so the second
12	 * arrival changes nothing and records nothing.
13	 *
14	 * This module sets a terminal `state` and deliberately leaves `completed_at`
15	 * null. The tick's finaliser owns `completed_at` and the ingestion that
16	 * follows, because `terminalRuns()` selects terminal runs with a null
17	 * `completed_at`, and a poll must not shortcut that.
18	 */
19	
20	import type { CalleDeps } from "./calle.ts";
21	import { recordCallEvent } from "./events.ts";
22	import type { CallStatus, CallTaskFixture } from "./fixtures.ts";
23	
24	/** The first follow-up is set by dispatch. Each pass after that waits ten. */
25	export const POLL_INTERVAL_MS = 10_000;
26	
27	/**
28	 * A run the provider never resolves is worse than a failed one, because it is
29	 * invisible. Give up well past the 140 seconds a real call took, and name the
30	 * reason on the run so an operator sees where it stopped.
31	 */
32	export const POLL_GIVE_UP_MS = 15 * 60_000;
33	
34	/** The terminal states the provider can report, mapped onto `call_runs.state`. */
35	export type TerminalState = "completed" | "failed" | "canceled";
36	
37	export type PollableRun = {
38	  id: string;
39	  state: string;
40	  poll_after: string | null;
41	};
42	
43	type RunRow = {
44	  id: string;
45	  state: string;
46	  calle_call_id: string | null;
47	  dispatched_at: string | null;
48	  poll_after: string | null;
49	  created_at: string;
50	};
51	
52	const PENDING_STATES = "in.(dispatched,awaiting_result)";
53	
54	function restUrl(base: string, path: string, query = ""): string {
55	  return `${base.replace(/\/+$/, "")}/rest/v1/${path}${query ? `?${query}` : ""}`;
56	}
57	
58	function serviceHeaders(key: string, prefer?: string): HeadersInit {
59	  const headers: Record<string, string> = {
60	    apikey: key,
61	    authorization: `Bearer ${key}`,
62	    "content-type": "application/json",
63	  };
64	  if (prefer) headers.prefer = prefer;
65	  return headers;
66	}
67	
68	export function terminalStateFor(status: CallStatus): TerminalState | null {
69	  if (status === "completed") return "completed";
70	  if (status === "failed") return "failed";
71	  if (status === "canceled") return "canceled";
72	  return null;
73	}
74	
75	/**
76	 * Re-fetches one authoritative call. It carries no run-state side effect, so
77	 * the tick's finaliser can reuse it for a run the webhook already terminalised.
78	 */
79	export async function fetchCall(
80	  callId: string,
81	  deps: CalleDeps,
82	): Promise<CallTaskFixture> {
83	  if (!callId) throw new Error("poll requires a CALL-E call id");
84	  const response = await deps.fetch(
85	    `${deps.calleApiBase.replace(/\/+$/, "")}/v1/calls/${encodeURIComponent(callId)}`,
86	    { headers: { authorization: `Bearer ${deps.calleApiKey}` } },
87	  );
88	  if (!response.ok) throw new Error(`CALL-E re-fetch returned HTTP ${response.status}`);
89	  const value: unknown = await response.json();
90	  if (typeof value !== "object" || value === null) {
91	    throw new Error("CALL-E re-fetch returned no call task");
92	  }
93	  const call = value as Partial<CallTaskFixture>;
94	  if (typeof call.id !== "string" || typeof call.status !== "string") {
95	    throw new Error("CALL-E re-fetch response missing id or status");
96	  }
97	  if (call.id !== callId) {
98	    throw new Error(`CALL-E re-fetch returned ${call.id} for ${callId}`);
99	  }
100	  return call as CallTaskFixture;
101	}
102	
103	async function readRun(deps: CalleDeps, runId: string): Promise<RunRow | null> {
104	  const query = new URLSearchParams({
105	    select: "id,state,calle_call_id,dispatched_at,poll_after,created_at",
106	    id: `eq.${runId}`,
107	    limit: "1",
108	  });
109	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
110	    headers: serviceHeaders(deps.serviceRoleKey),
111	  });
112	  if (!response.ok) throw new Error("call_runs poll read failed");
113	  const rows = await response.json() as RunRow[];
114	  return rows[0] ?? null;
115	}
116	
117	/**
118	 * Applies a patch only while the run is still pending, and reports whether
119	 * this caller was the one that won. Returning the representation is what makes
120	 * the loss observable rather than assumed.
121	 */
122	async function patchPendingRun(
123	  deps: CalleDeps,
124	  runId: string,
125	  patch: Record<string, unknown>,
126	): Promise<boolean> {
127	  const query = new URLSearchParams({ id: `eq.${runId}`, state: PENDING_STATES });
128	  const response = await deps.fetch(restUrl(deps.apiUrl, "call_runs", query.toString()), {
129	    method: "PATCH",
130	    headers: serviceHeaders(deps.serviceRoleKey, "return=representation"),
131	    body: JSON.stringify(patch),
132	  });
133	  if (!response.ok) throw new Error("call_runs poll update failed");
134	  const rows = await response.json() as unknown[];
135	  return Array.isArray(rows) && rows.length === 1;
136	}
137	
138	function failure(code: string, message: string): Record<string, string> {
139	  return { failure_code: code, failure_message: message };
140	}
141	
142	async function reschedule(
143	  deps: CalleDeps,
144	  runId: string,
145	  callId: string | null,
146	  detail: Record<string, string | number | boolean | null>,
147	): Promise<void> {
148	  const pollAfter = new Date(deps.now().getTime() + POLL_INTERVAL_MS).toISOString();
149	  const won = await patchPendingRun(deps, runId, { poll_after: pollAfter });
150	  if (!won) return;
151	  await recordCallEvent(runId, "polled", { calle_call_id: callId, ...detail }, deps);
152	}
153	
154	/**
155	 * Advances one pending run by one poll pass. A transport failure, a provider
156	 * error or an unparseable body reschedules the next pass instead of throwing,
157	 * so one poisoned run cannot fail the whole tick.
158	 */
159	export async function pollRun(run: PollableRun, deps: CalleDeps): Promise<void> {
160	  const current = await readRun(deps, run.id);
161	  // The webhook may have terminalised this run between the tick's read and
162	  // this call. That is the race, and losing it is a no-op.
