1	/**
2	 * The operator timeline outlives any one Edge Function invocation. Each call
3	 * transition writes one append-only row, which makes a run legible without
4	 * relying on scattered function logs.
5	 */
6	
7	export const CALL_EVENT_KINDS = [
8	  "materialised",
9	  "claimed",
10	  "dispatched",
11	  "polled",
12	  "webhook_received",
13	  "refetched",
14	  "ingested",
15	  "finalised",
16	] as const;
17	
18	export type CallEventKind = typeof CALL_EVENT_KINDS[number];
19	export type CallEventDetail = Record<string, JsonValue>;
20	export type JsonValue = string | number | boolean | null | JsonValue[] | {
21	  [key: string]: JsonValue;
22	};
23	
24	export type EventDeps = {
25	  apiUrl: string;
26	  serviceRoleKey: string;
27	  fetch: typeof fetch;
28	};
29	
30	function apiBase(apiUrl: string): string {
31	  const base = apiUrl.replace(/\/+$/, "");
32	  if (base.includes("supabase.co")) {
33	    throw new Error("must use ORMA_API_URL, not project host");
34	  }
35	  return base;
36	}
37	
38	function eventHeaders(serviceRoleKey: string): HeadersInit {
39	  return {
40	    apikey: serviceRoleKey,
41	    authorization: `Bearer ${serviceRoleKey}`,
42	    "content-type": "application/json",
43	    prefer: "return=minimal",
44	  };
45	}
46	
47	function isEventKind(value: string): value is CallEventKind {
48	  return (CALL_EVENT_KINDS as readonly string[]).includes(value);
49	}
50	
51	function nonBlankString(value: JsonValue | undefined): value is string {
52	  return typeof value === "string" && value.trim().length > 0;
53	}
54	
55	function isFailureState(state: string): boolean {
56	  return /(?:fail|error|cancel)/i.test(state);
57	}
58	
59	function assertTerminalDetail(detail: CallEventDetail): void {
60	  if (!nonBlankString(detail.state)) {
61	    throw new Error("finalised call event requires a terminal state");
62	  }
63	  if (isFailureState(detail.state) && !nonBlankString(detail.failure_reason)) {
64	    throw new Error("failed finalised call event requires a failure reason");
65	  }
66	}
