68	/**
69	 * Appends the transition to the run's timeline. Callers must include the
70	 * provider identifier, state, failure reason, or other durable observation
71	 * that explains this transition. Never put secrets or unmasked numbers here.
72	 */
73	export async function recordCallEvent(
74	  callRunId: string,
75	  kind: CallEventKind,
76	  detail: CallEventDetail,
77	  deps: EventDeps,
78	): Promise<void> {
79	  if (!callRunId) throw new Error("call event requires a call run id");
80	  if (!isEventKind(kind)) {
81	    throw new Error(`unsupported call event kind: ${kind}`);
82	  }
83	  if (kind === "finalised") assertTerminalDetail(detail);
84	
85	  const response = await deps.fetch(
86	    `${apiBase(deps.apiUrl)}/rest/v1/call_events`,
87	    {
88	      method: "POST",
89	      headers: eventHeaders(deps.serviceRoleKey),
90	      body: JSON.stringify({ call_run_id: callRunId, kind, detail }),
91	    },
92	  );
93	  if (!response.ok) throw new Error("call event insert failed");
94	}
