96	const testFn =
97	  (Deno as { test?: (name: string, fn: () => void | Promise<void>) => void })
98	    .test;
99	
100	if (typeof testFn === "function") {
101	  testFn(
102	    "records an append-only timeline row with durable detail",
103	    async () => {
104	      let request: Request | undefined;
105	      await recordCallEvent(
106	        "run-1",
107	        "dispatched",
108	        { calle_call_id: "call_123", state: "awaiting_result" },
109	        {
110	          apiUrl: "https://orma-api.nryn.dev",
111	          serviceRoleKey: "service-key",
112	          fetch: async (input, init) => {
113	            request = new Request(input, init);
114	            return new Response(null, { status: 201 });
115	          },
116	        },
117	      );
118	      if (!request || request.method !== "POST") {
119	        throw new Error("timeline must append with POST");
120	      }
121	      if (!request.url.endsWith("/rest/v1/call_events")) {
122	        throw new Error("timeline must write call_events");
123	      }
