131	      }
132	      if (row.detail.calle_call_id !== "call_123") {
133	        throw new Error("timeline row lost its durable detail");
134	      }
135	    },
136	  );
137	
138	  testFn(
139	    "rejects an unknown transition before it reaches the database",
140	    async () => {
141	      let called = false;
142	      try {
143	        await recordCallEvent(
144	          "run-1",
