153	            },
154	          },
155	        );
156	        throw new Error("unknown transition was accepted");
157	      } catch (error) {
158	        if (
159	          !(error instanceof Error) ||
160	          error.message !== "unsupported call event kind: logged"
161	        ) {
162	          throw error;
163	        }
164	      }
165	      if (called) throw new Error("unknown transition reached the database");
166	    },
167	  );
168	
