184	            },
185	          },
186	        );
187	        throw new Error("opaque terminal failure was accepted");
188	      } catch (error) {
189	        if (
190	          !(error instanceof Error) ||
191	          error.message !== "failed finalised call event requires a failure reason"
192	        ) {
193	          throw error;
194	        }
195	      }
196	      if (called) throw new Error("opaque terminal failure reached the database");
197	    },
