1	/**
2	 * T2.5 review round 3 live pins. Drives the real tick handler, webhook handler,
3	 * pollRun, fetchCall and ingestTerminalRun from ROOT (default: the frozen copy)
4	 * against the scratch stack. Only the CALL-E transport is a stub. Every claim is
5	 * a separate psql read scoped to idempotency_key like 'rev3-t25-%'.
6	 */
7	const ROOT = Deno.env.get("ROOT") ?? "/tmp/orma-review-t25-r3";
8	const { createTickHandler, depsFromEnv: tickDepsFromEnv } = await import(`${ROOT}/supabase/functions/tick/index.ts`);
9	const { createWebhookHandler, depsFromEnv: webhookDepsFromEnv } = await import(`${ROOT}/supabase/functions/calle-webhook/index.ts`);
10	const { depsFromEnv: calleDepsFromEnv } = await import(`${ROOT}/supabase/functions/_shared/calle.ts`);
11	const { pollRun, fetchCall, POLL_GIVE_UP_MS } = await import(`${ROOT}/supabase/functions/_shared/poll.ts`);
12	const { ingestTerminalRun } = await import(`${ROOT}/supabase/functions/_shared/ingest.ts`);
13	
14	const API = Deno.env.get("ORMA_API_URL")!;
15	const KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
16	const SECRET = Deno.env.get("ORMA_WEBHOOK_SECRET")!;
17	const USER = "00000000-0000-4000-8000-000000000001";
18	if (Deno.env.get("CALLE_API_BASE") !== "https://api.call-e.test") throw new Error("refusing: CALLE_API_BASE is not the stub host");
19	
20	const headers = { apikey: KEY, authorization: `Bearer ${KEY}`, "content-type": "application/json" };
21	const rest = (path: string, init: RequestInit = {}) =>
22	  fetch(`${API}/rest/v1/${path}`, { ...init, headers: { ...headers, ...(init.headers ?? {}) } });
23	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
24	
25	type Fake = { status: string; delayMs?: number; httpStatus?: number; body?: Record<string, unknown> };
26	const fakes = new Map<string, Fake>();
27	const runByCall = new Map<string, string>();
28	const refetches = new Map<string, number>();
29	const stub: typeof fetch = async (input, init) => {
30	  const request = new Request(input, init);
31	  const url = new URL(request.url);
32	  if (url.host === "api.call-e.test") {
33	    if (request.method !== "GET") return new Response(null, { status: 599 });
34	    const id = url.pathname.split("/").pop()!;
35	    const fake = fakes.get(id);
36	    if (!fake) return new Response(null, { status: 404 });
37	    if (fake.delayMs) await sleep(fake.delayMs);
38	    refetches.set(id, (refetches.get(id) ?? 0) + 1);
39	    if (fake.httpStatus) return new Response(null, { status: fake.httpStatus });
40	    return Response.json({
41	      completion_confidence: null, failure_code: null, ...(fake.body ?? {}),
42	      id, status: fake.status, metadata: { call_run_id: runByCall.get(id) },
43	    });
44	  }
45	  if (url.origin !== new URL(API).origin) throw new Error(`refusing outbound request to ${url.host}`);
46	  return await fetch(request);
47	};
48	const env = (k: string) => Deno.env.get(k);
49	
50	async function guardForeignRows(): Promise<void> {
51	  const response = await rest(
52	    "call_runs?select=id&idempotency_key=not.like.rev3-t25-*&or=(state.in.(scheduled,claimed,dispatched,awaiting_result),and(state.in.(completed,no_result,failed,canceled),completed_at.is.null))",
53	  );
54	  const foreign = await response.json() as unknown[];
55	  if (!Array.isArray(foreign) || foreign.length !== 0) {
56	    throw new Error(`refusing to tick: foreign rows are claimable, pollable or finalisable: ${JSON.stringify(foreign)}`);
57	  }
58	}
59	
60	async function createRun(label: string, patch: Record<string, unknown>, callId: string | null): Promise<string> {
61	  const id = crypto.randomUUID();
62	  if (callId) runByCall.set(callId, id);
63	  const response = await rest("call_runs", {
64	    method: "POST",
65	    body: JSON.stringify({
66	      id, user_id: USER, local_date: "2026-09-13", part_of_day: `rev3-${label}`,
67	      scheduled_for: new Date().toISOString(), idempotency_key: `rev3-t25-${label}-${id}`,
68	      calle_call_id: callId, ...patch,
69	    }),
70	  });
71	  if (!response.ok) throw new Error(`create ${label} failed ${response.status} ${await response.text()}`);
72	  console.log(`${label}=${id}`);
73	  return id;
74	}
75	
76	async function deliver(callId: string, eventId: string, fetchImpl: typeof fetch = stub, type = "call.completed"): Promise<number> {
77	  const envelope = { id: eventId, type, created_at: new Date().toISOString(), data: { id: callId } };
78	  const response = await createWebhookHandler(webhookDepsFromEnv(env, fetchImpl))(
79	    new Request(`${API}/functions/v1/calle-webhook/${SECRET}`, {
80	      method: "POST", headers: { "call-e-event-id": eventId }, body: JSON.stringify(envelope),
81	    }),
82	  );
83	  return response.status;
84	}
85	
86	const mode = Deno.args[0];
87	const tag = crypto.randomUUID().slice(0, 6);
88	const ago = (ms: number) => new Date(Date.now() - ms).toISOString();
89	const later = (ms: number) => new Date(Date.now() + ms).toISOString();
90	const poll = (id: string, f: typeof fetch = stub) =>
91	  pollRun({ id, state: "awaiting_result", poll_after: null }, calleDepsFromEnv(env, f));
92	
93	if (mode === "T") {
94	  // Round 1 H and round 2 second L. The finalise stub throws, the sibling poll lands.
95	  const t = `call_rev3_tterm_${tag}`, s = `call_rev3_tsib_${tag}`;
96	  await createRun("T-terminal", { state: "completed", dispatched_at: ago(180_000) }, t);
97	  await createRun("T-sibling", { state: "awaiting_result", dispatched_at: ago(120_000), poll_after: ago(1_000) }, s);
98	  fakes.set(s, { status: "completed" });
99	  await guardForeignRows();
100	  const response = await createTickHandler(tickDepsFromEnv(env, stub))(new Request(`${API}/functions/v1/tick`, { method: "POST" }));
101	  console.log(`T-tick-status=${response.status} body=${await response.text()}`);
102	}
103	
104	if (mode === "M") {
105	  // Round 1 M. No dispatched_at, created_at past the window, poll_after sliding.
106	  const c = `call_rev3_m_${tag}`;
107	  const id = await createRun("M-no-dispatched-at", { state: "awaiting_result", dispatched_at: null, created_at: ago(POLL_GIVE_UP_MS + 120_000), poll_after: ago(1_000) }, c);
108	  fakes.set(c, { status: "in_progress" });
109	  await poll(id);
110	  console.log(`M-refetches=${refetches.get(c) ?? 0}`);
111	}
112	
113	if (mode === "L") {
114	  // Round 1 L. The poll wins, the late webhook re-fetches failed.
115	  const c = `call_rev3_l_${tag}`;
116	  const id = await createRun("L-poll-wins", { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: ago(1_000) }, c);
117	  fakes.set(c, { status: "completed" });
118	  await poll(id);
119	  fakes.set(c, { status: "failed" });
120	  console.log(`L-webhook-status=${await deliver(c, `evt_rev3_l_${tag}`, stub, "call.failed")}`);
121	}
122	
123	if (mode === "A") {
124	  // Round 2 H. Overdue, CALL-E reports completed.
125	  const c = `call_rev3_a_${tag}`;
126	  const id = await createRun("A-overdue-completed", { state: "awaiting_result", dispatched_at: ago(POLL_GIVE_UP_MS + 60_000), poll_after: ago(1_000) }, c);
127	  fakes.set(c, { status: "completed" });
128	  await poll(id);
129	  console.log(`A-refetches=${refetches.get(c) ?? 0}`);
130	}
131	
132	if (mode === "B") {
133	  // Round 2 first L. The webhook's own write lands, then its first timeline insert fails once.
134	  const c = `call_rev3_b_${tag}`;
135	  await createRun("B-retried", { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: later(3_600_000) }, c);
136	  fakes.set(c, { status: "completed" });
137	  let failed = false;
138	  const flaky: typeof fetch = async (input, init) => {
139	    const request = new Request(input, init);
140	    if (!failed && request.method === "POST" && new URL(request.url).pathname.endsWith("/call_events")) {
141	      failed = true;
142	      return new Response(null, { status: 503 });
143	    }
144	    return await stub(request);
145	  };
146	  const eventId = `evt_rev3_b_${tag}`;
147	  console.log(`B-first=${await deliver(c, eventId, flaky)} B-redelivery=${await deliver(c, eventId, flaky)}`);
148	}
149	
150	if (mode === "F1a") {
151	  // New. Two distinct terminal events for one call. Event 1 applies. Event 2's first
152	  // attempt fails on its re-fetch, so its retry arrives as a 409 redelivery.
153	  const c = `call_rev3_f1a_${tag}`;
154	  await createRun("F1a-two-events", { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: later(3_600_000) }, c);
155	  fakes.set(c, { status: "completed" });
156	  console.log(`F1a-event1=${await deliver(c, `evt_rev3_f1a_one_${tag}`)}`);
157	  fakes.set(c, { status: "completed", httpStatus: 503 });
158	  console.log(`F1a-event2-first=${await deliver(c, `evt_rev3_f1a_two_${tag}`, stub, "call.result_validation_failed")}`);
159	  fakes.set(c, { status: "completed" });
160	  console.log(`F1a-event2-redelivery=${await deliver(c, `evt_rev3_f1a_two_${tag}`, stub, "call.result_validation_failed")}`);
161	}
162	
163	if (mode === "F1b") {
164	  // New, the remediator's open item. The webhook's first attempt fails on re-fetch.
165	  // The poll then moves the run, and its polled insert fails. The redelivery follows.
166	  const c = `call_rev3_f1b_${tag}`;
167	  const id = await createRun("F1b-poll-row-lost", { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: ago(1_000) }, c);
168	  const eventId = `evt_rev3_f1b_${tag}`;
169	  fakes.set(c, { status: "completed", httpStatus: 503 });
170	  console.log(`F1b-first=${await deliver(c, eventId)}`);
171	  fakes.set(c, { status: "completed" });
172	  const eventsDown: typeof fetch = async (input, init) => {
173	    const request = new Request(input, init);
174	    if (request.method === "POST" && new URL(request.url).pathname.endsWith("/call_events")) return new Response("{}", { status: 503 });
175	    return await stub(request);
176	  };
177	  try {
178	    await poll(id, eventsDown);
179	    console.log("F1b-poll=resolved");
180	  } catch (error) {
181	    console.log(`F1b-poll=threw ${(error as Error).message}`);
182	  }
183	  console.log(`F1b-redelivery=${await deliver(c, eventId)}`);
184	}
185	
186	if (mode === "F1c") {
187	  // New. The redelivery races a healthy poll. The poll's PATCH lands first, and the
188	  // redelivery reads call_events before the poll's polled row is inserted.
189	  for (let round = 1; round <= 3; round++) {
190	    const c = `call_rev3_f1c_${round}_${tag}`;
191	    const id = await createRun(`F1c-race-${round}`, { state: "awaiting_result", dispatched_at: ago(90_000), poll_after: ago(1_000) }, c);
192	    const eventId = `evt_rev3_f1c_${round}_${tag}`;
193	    fakes.set(c, { status: "completed", httpStatus: 503 });
194	    const first = await deliver(c, eventId);
195	    fakes.set(c, { status: "completed" });
196	    const slowEvents: typeof fetch = async (input, init) => {
197	      const request = new Request(input, init);
198	      if (request.method === "POST" && new URL(request.url).pathname.endsWith("/call_events")) await sleep(600);
199	      return await stub(request);
200	    };
201	    const slowRefetch: typeof fetch = async (input, init) => {
202	      const request = new Request(input, init);
203	      if (new URL(request.url).host === "api.call-e.test") await sleep(200);
204	      return await stub(request);
205	    };
206	    const [, status] = await Promise.all([poll(id, slowEvents), deliver(c, eventId, slowRefetch)]);
207	    console.log(`F1c-${round} first=${first} redelivery=${status}`);
208	  }
209	}
210	
211	if (mode === "R" || mode === "RO") {
212	  // Exactly one winner. RO makes the run overdue, so the poll's pending re-fetch
213	  // gives up while the webhook's re-fetch reports completed.
214	  const overdue = mode === "RO";
215	  for (const order of ["poll-first", "webhook-first"]) {
216	    for (let round = 1; round <= 3; round++) {
217	      const c = `call_rev3_${mode}_${order}_${round}_${tag}`;
218	      const id = await createRun(`${mode}-${order}-${round}`, {
219	        state: "awaiting_result", poll_after: ago(1_000),
220	        dispatched_at: overdue ? ago(POLL_GIVE_UP_MS + 60_000) : ago(90_000),
221	      }, c);
222	      fakes.set(c, { status: overdue ? "in_progress" : "completed" });
223	      const pollStub: typeof fetch = async (input, init) => {
224	        const request = new Request(input, init);
225	        if (order === "webhook-first" && new URL(request.url).host === "api.call-e.test") await sleep(150);
226	        return await stub(request);
227	      };
228	      const hookStub: typeof fetch = async (input, init) => {
229	        const request = new Request(input, init);
230	        if (new URL(request.url).host === "api.call-e.test") {
231	          const body = await (await stub(request)).json();
232	          body.status = overdue ? "completed" : "failed";
233	          if (order === "poll-first") await sleep(150);
234	          return Response.json(body);
235	        }
236	        return await stub(request);
237	      };
238	      const [, status] = await Promise.all([
239	        poll(id, pollStub),
240	        deliver(c, `evt_rev3_${mode}_${order}_${round}_${tag}`, hookStub, overdue ? "call.completed" : "call.failed"),
241	      ]);
242	      console.log(`${mode}-${order}-${round} webhook=${status}`);
243	    }
244	  }
245	}
246	
247	if (mode === "F2") {
248	  // New. Overdue run, one failed re-fetch, poll gives up. The finaliser as T2.7a
249	  // specifies it then re-fetches and ingests the call CALL-E reports completed.
250	  const c = `call_rev3_f2_${tag}`;
251	  const id = await createRun("F2-giveup-then-finalise", { state: "awaiting_result", dispatched_at: ago(POLL_GIVE_UP_MS + 60_000), poll_after: ago(1_000) }, c);
252	  fakes.set(c, { status: "completed", httpStatus: 503 });
253	  await poll(id);
254	  console.log("F2-after-poll");
255	  const fixture = JSON.parse(await Deno.readTextFile(`${ROOT}/testdata/calle/call-completed.json`));
256	  fakes.set(c, { status: "completed", body: { ...fixture, failure_code: null, failure_message: null } });
257	  const call = await fetchCall(c, calleDepsFromEnv(env, stub)) as Record<string, unknown>;
258	  const attempts = (call.attempts as { transcript_turns?: unknown[] }[] | undefined) ?? [];
259	  const result = await ingestTerminalRun({
260	    callRunId: id, userId: USER, raw: call,
261	    transcriptTurns: (attempts[0]?.transcript_turns ?? []) as never, structuredResult: null,
262	  }, { apiUrl: API, serviceRoleKey: KEY, fetch: stub });
263	  console.log(`F2-ingest disposition=${result.disposition} already=${result.alreadyIngested}`);
264	}
